def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally outcomes and streaks compactly
    my_score = 0
    opp_score = 0
    opp_c = 0
    my_c = 0
    last_opp = history[-1][1]
    last_me = history[-1][0]

    opp_def_streak = 0
    my_def_streak = 0
    opp_c_streak = 0
    my_c_streak = 0
    opp_def_streak_done = False
    my_def_streak_done = False
    opp_c_streak_done = False
    my_c_streak_done = False

    for i in range(n - 1, -1, -1):
        a, b = history[i]
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

        if not opp_def_streak_done:
            if b == 'D':
                opp_def_streak += 1
            else:
                opp_def_streak_done = True
        if not my_def_streak_done:
            if a == 'D':
                my_def_streak += 1
            else:
                my_def_streak_done = True
        if not opp_c_streak_done:
            if b == 'C':
                opp_c_streak += 1
            else:
                opp_c_streak_done = True
        if not my_c_streak_done:
            if a == 'C':
                my_c_streak += 1
            else:
                my_c_streak_done = True

    rounds_left = 100 - n
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Opening
    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'
    if n == 2:
        # Forgive an isolated defection
        if history[0][1] == 'D' and history[1][1] == 'C':
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Detect all-cooperate opponent for safe endgame exploitation
    if opp_def_streak_done and opp_c == n:
        # Everything so far is cooperation
        if rounds_left <= 2:
            return 'D'
        return 'C'

    # Endgame handling
    if rounds_left <= 2:
        if last_opp == 'C':
            return 'D'
        return 'D'

    if rounds_left <= 5:
        if opp_rate >= 0.75:
            return 'C'
        if opp_rate <= 0.35:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Extreme defectors: retaliate but keep probing sometimes
    if opp_rate <= 0.20:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # High cooperation: preserve mutual cooperation, exploit sparingly
    if opp_rate >= 0.80:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # Long mutual cooperation but not perfect -> keep it
    if opp_c_streak >= 8 and my_c_streak >= 8:
        if rounds_left <= 15 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent just defected: short punishment, forgive if they return to C
    if last_opp == 'D':
        if opp_def_streak >= 4:
            # persistent defector
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if opp_def_streak == 3:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if opp_def_streak == 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # isolated defection
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_opp == 'C':
        # If we defected and just got cooperation, return to cooperation
        if last_me == 'D':
            return 'C'
        # Exploit trailing cooperators late
        if rounds_left <= 20 and opp_rate >= 0.7 and my_c_streak >= 5:
            if rng.random() < 0.25:
                return 'D'
        # Probe a very cooperative streak rarely
        if opp_c_streak >= 12 and rounds_left > 25:
            if rng.random() < 0.06:
                return 'D'
            return 'C'
        if opp_rate >= 0.5:
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    return 'C'
